<script setup lang="ts">
import {computed,onMounted,onUnmounted,ref,watch} from 'vue';
import * as L from 'leaflet';
import 'leaflet/dist/leaflet.css';
import {planBuildings,isRoomInPlanBuilding,type PlanTarget} from '../services/campus-plan';
import {campusRooms} from '../services/campus-rooms';
const props=defineProps<{target?:PlanTarget}>();
const emit=defineEmits<{showRooms:[target:PlanTarget]}>();
const campus=ref<'east'|'west'>(props.target?.campus||'west'),element=ref<HTMLElement>(),selected=ref(props.target),imageFailed=ref(false);
const buildings=computed(()=>planBuildings.filter(b=>b.campus===campus.value));
const roomCount=computed(()=>selected.value?campusRooms.filter(r=>isRoomInPlanBuilding(r,selected.value!)).length:0);
let map:L.Map|undefined,overlay:L.ImageOverlay|undefined,markers:L.LayerGroup|undefined,resize:ResizeObserver|undefined;
function fullView(){if(!map)return;const h=campus.value==='west'?1222:1536;map.fitBounds(campus.value==='west'?[[h-740,45],[h-150,820]]:[[h-1200,0],[h-350,709]],{animate:false,padding:[8,8]})}
function drawMarkers(){if(!map||!markers)return;markers.eachLayer(layer=>layer.unbindTooltip());markers.clearLayers();const h=campus.value==='west'?1222:1536;for(const b of buildings.value){const active=selected.value?.name===b.name;const marker=L.circleMarker([h-b.y,b.x],{radius:active?12:9,color:active?'#d34f37':'#456e9a',weight:3,fillColor:'#fff',fillOpacity:.75}).addTo(markers);const label=document.createElement('span');label.textContent=b.name+' · 楼栋参考点';marker.bindTooltip(label,{permanent:active,direction:'top'});marker.on('click',()=>focus(b))}}
function focus(b:PlanTarget){selected.value=b;drawMarkers();const h=b.campus==='west'?1222:1536;map?.setView([h-b.y,b.x],0,{animate:false})}
function pick(event:Event){const b=buildings.value.find(b=>b.name===(event.target as HTMLSelectElement).value);if(b)focus(b)}
function load(){if(!map)return;overlay?.remove();imageFailed.value=false;const west=campus.value==='west',width=west?864:709,height=west?1222:1536;overlay=L.imageOverlay(`/campus/${campus.value}-plan.jpg`,[[0,0],[height,width]]).on('error',()=>{imageFailed.value=true}).addTo(map);drawMarkers();fullView();if(selected.value?.campus===campus.value)focus(selected.value)}
watch(campus,()=>{selected.value=undefined;load()});
onMounted(()=>{if(!element.value)return;map=L.map(element.value,{crs:L.CRS.Simple,zoomAnimation:false,fadeAnimation:false,zoomSnap:.1,minZoom:-3,maxZoom:3,attributionControl:false});markers=L.layerGroup().addTo(map);load();resize=new ResizeObserver(()=>map?.invalidateSize({pan:false}));resize.observe(element.value)});
onUnmounted(()=>{resize?.disconnect();map?.remove()});
</script>
<template><section class="plan"><div class="plan-switch"><button :class="{active:campus==='west'}" @click="campus='west'">西校区平面图</button><button :class="{active:campus==='east'}" @click="campus='east'">东校区平面图</button></div><div ref="element" class="canvas" aria-label="校园平面图，可双指缩放"/><p v-if="imageFailed" role="status">平面图加载失败，<button @click="load">重新加载</button></p><div class="plan-tools"><button @click="fullView">显示全图</button><button v-if="selected" @click="focus(selected)">回到所选楼栋</button></div><article v-if="selected" class="building-detail"><strong>{{selected.name}}</strong><p>已收录 {{roomCount}} 条教室与场地记录</p><button @click="emit('showRooms',selected)">查看这栋楼的教室</button></article><label class="building-picker">选择楼栋<select aria-label="在平面图选择楼栋" :value="selected?.name||''" @change="pick"><option value="" disabled>点击图上圆点，或在此选择</option><option v-for="b in buildings" :key="b.name" :value="b.name">{{b.name}}</option></select></label><p>双指缩放、拖动查看楼名。圆点为图上楼栋参考位置。</p><details><summary>图源与精度</summary><p>平面图由用户提供，版本日期待核对。尚未标定经纬度，个人定位在“道路与地点”查看。已匹配西区七座教学楼及东区文理综合楼 A—E 区，其余楼栋仍待核对。</p></details></section></template>
<style scoped>.plan-switch,.plan-tools{display:flex;gap:8px;margin:12px 0}.plan-switch button,.plan-tools button,.building-detail button{flex:1;min-height:42px;padding:10px;border:1px solid var(--color-border);border-radius:10px;background:var(--color-surface);color:var(--color-text);font-size:12px}.plan-switch .active,.building-detail button{background:var(--color-primary);color:#fff}.canvas{height:48dvh;min-height:300px;isolation:isolate;background:#f6f5ed;border-radius:14px}.plan p,.plan details{font-size:11px;color:var(--color-muted);line-height:1.65}.building-detail{padding:14px;border-radius:12px;background:var(--color-bg);font-size:14px}.building-detail button{width:100%}.building-picker{display:block;margin:14px 0;font-size:12px;color:var(--color-muted)}.building-picker select{display:block;width:100%;margin-top:7px;min-height:42px;background:var(--color-surface);color:var(--color-text);border:1px solid var(--color-border);border-radius:10px;padding:8px}</style>
